def require(value, message):
    if not value:
        raise RuntimeError(message)


def _identity(path):
    info = path.lstat()
    return (info.st_dev, info.st_ino, info.st_mode, info.st_uid, info.st_gid,
            info.st_nlink, info.st_size, info.st_mtime_ns, info.st_ctime_ns)


def _native_sources(runtime):
    require(runtime.is_absolute() and runtime.resolve(strict=True) == runtime
            and runtime.name == 'openclaw' and runtime.parent.name == 'node_modules',
            'Catalog derivation requires the verified native package.')
    package = json.loads((runtime / 'package.json').read_bytes())
    require(package.get('name') == 'openclaw' and package.get('version') == '2026.9.8',
            'Catalog derivation runtime version changed.')
    require(len(NATIVE_SOURCE_PINS) > 100, 'Catalog native source closure is unbound.')
    identities = {}
    for name, expected in NATIVE_SOURCE_PINS.items():
        path = runtime / name
        require(path.resolve(strict=True) == path and path.is_file()
                and not path.is_symlink() and path.stat().st_size <= 4 * MAXIMUM,
                'Catalog native implementation was redirected.')
        identities[path] = _identity(path)
        require(hashlib.sha256(path.read_bytes()).hexdigest() == expected
                and _identity(path) == identities[path], 'Catalog native implementation changed.')
    return identities


def _plugin_files(record, root, manifest, plugin_id, current):
    from recovery import catalog_file, digest
    relative = Path('dist/service/apps/service') / APP_PLUGINS[plugin_id]
    plugin = root / relative
    require(root.resolve(strict=True) == root and plugin.resolve(strict=True) == plugin
            and record.get('rootDir') == str(plugin) and record.get('source') == str(plugin / 'index.js')
            and record.get('manifestPath') == str(plugin / 'openclaw.plugin.json'),
            'Application catalog root differs from its candidate.')
    artifacts = {item['path']: item['sha256'] for item in manifest['artifacts']
                 if item['path'].startswith(relative.as_posix() + '/')}
    actual = {}
    require(0 < len(artifacts) <= 1000, 'Application catalog lacks its bounded artifact closure.')
    for path in plugin.rglob('*'):
        require(not path.is_symlink() and (path.is_file() or path.is_dir()),
                'Application plugin artifact was redirected.')
        if path.is_file():
            require(len(actual) < 1000, 'Application plugin artifact closure exceeded its bound.')
            actual[path.relative_to(root).as_posix()] = digest(path)
    require(actual == artifacts, 'Application catalog artifact differs from its candidate.')
    package = record.get('packageJson')
    require(type(package) is dict and set(package) == {'path', 'hash', 'fileSignature'}
            and package['path'] == 'package.json', 'Application catalog package identity changed.')
    native_manifest = json.loads(catalog_file(plugin / 'openclaw.plugin.json', record.get('manifestHash'),
                                             record.get('manifestFile'), current=current))
    package_value = json.loads(catalog_file(plugin / 'package.json', package['hash'],
                                           package['fileSignature'], current=current))
    require(native_manifest.get('id') == plugin_id and package_value.get('name') == record.get('packageName')
            and package_value.get('version') == record.get('packageVersion'),
            'Application catalog manifest identity differs.')
    return str(plugin)


def _comparable_record(record):
    """Only historical ctime is copy-local; all content/semantic fields remain."""
    result = copy.deepcopy(record)
    for signature in (result.get('manifestFile'), result.get('packageJson', {}).get('fileSignature')):
        require(type(signature) is dict and set(signature) == {'size', 'mtimeMs', 'ctimeMs'},
                'Application catalog file signature is absent.')
        del signature['ctimeMs']
    return result


def _normalize(indexes, derived):
    """Pure admission seam, also exercised with complete forged negative records."""
    require(type(derived) is dict and set(derived) == {'format', 'nativeVersion', 'sides'}
            and derived['format'] == 1 and derived['nativeVersion'] == '2026.9.8'
            and type(derived['sides']) is list and len(derived['sides']) == 2,
            'Native catalog derivation returned an invalid envelope.')
    before, after = copy.deepcopy(indexes)
    ids = [[row['pluginId'] for row in index['plugins']] for index in (before, after)]
    require(all(len(row) == len(set(row)) for row in ids) and DIRECT not in ids[0]
            and ids[1].count(DIRECT) == 1 and [name for name in ids[1] if name != DIRECT] == ids[0],
            'Application catalog changed unrelated membership or order.')
    require(before['installRecords'] == after['installRecords']
            and before['diagnostics'] == after['diagnostics'],
            'Application catalog changed installations or diagnostics.')
    for position, index in enumerate((before, after)):
        value = derived['sides'][position]
        require(type(value) is dict and set(value) == {'index', 'policyHash', 'memoryEnabled'},
                'Native catalog derivation changed shape.')
        expected_ids = set(APP_PLUGINS) - ({DIRECT} if position == 0 else set())
        observed = [row for row in index['plugins'] if row['pluginId'] in APP_PLUGINS]
        native = value['index']
        require({row['pluginId'] for row in observed} == expected_ids
                and [row['pluginId'] for row in native['plugins']] == [row['pluginId'] for row in observed]
                and native['diagnostics'] == [] and native['installRecords'] == index['installRecords']
                and all(native[key] == index[key] for key in
                        ('version', 'warning', 'hostContractVersion', 'compatRegistryVersion', 'migrationVersion')),
                'Native catalog did not reproduce exact application membership and authority.')
        require(len(native['plugins']) == len(observed)
                and all(_comparable_record(a) == _comparable_record(b)
                        for a, b in zip(observed, native['plugins'])),
                'Application catalog semantics differ from official physical derivation.')
        require(value['policyHash'] == index['policyHash'] and native['policyHash'] == index['policyHash'],
                'Application catalog policy hash differs from official derivation.')
        memories = [row for row in index['plugins'] if row['pluginId'] == 'memory-core']
        require(len(memories) == 1 and type(value['memoryEnabled']) is bool
                and memories[0].get('enabled') is value['memoryEnabled'],
                'Memory plugin enablement differs from official policy.')
    old_rows = {row['pluginId']: row for row in before['plugins']}
    new_rows = {row['pluginId']: row for row in after['plugins']}
    memory = copy.deepcopy(new_rows['memory-core']); memory['enabled'] = old_rows['memory-core']['enabled']
    require(memory == old_rows['memory-core'], 'Memory plugin changed beyond derived enablement.')
    after['plugins'] = [copy.deepcopy(old_rows[row['pluginId']]) if row['pluginId'] in APP_PLUGINS
                        else memory if row['pluginId'] == 'memory-core' else row
                        for row in after['plugins'] if row['pluginId'] != DIRECT]
    after['policyHash'] = before['policyHash']
    return [before, after]


def qualify_application_catalog(indexes, *, node, app_releases, workspace_roots, configuration,
                                startup_window, catalog_runtime_root, transition):
    from recovery import (_VERIFICATION_SCRATCH, RESERVE, ALLOWANCE, catalog_file, digest,
                          sqlite_source_identity, verify_sqlite_wal, validate_application_transition)
    require(type(transition) is dict and set(transition) == {'transition', 'beforeRoot', 'afterRoot',
            'fromSchemaVersion', 'toSchemaVersion', 'restored'} and transition['restored'] is False
            and transition['fromSchemaVersion'] == 55 and transition['toSchemaVersion'] == 60,
            'Application catalog transition scope changed.')
    validate_application_transition(transition['transition'])
    require(type(indexes) in (tuple, list) and len(indexes) == 2
            and app_releases is not None and len(app_releases) == 2
            and workspace_roots is not None and len(workspace_roots) == 4,
            'Application catalog lacks bound retained roles.')
    snapshot, live, logical, selected = map(Path, workspace_roots)
    require(snapshot == transition['beforeRoot'] and live == transition['afterRoot']
            and logical == live and not selected.is_absolute() and '..' not in selected.parts,
            'Application catalog is outside its hosted retained namespace.')
    relative = selected / 'openclaw-runtime/openclaw.json'
    require(type(configuration) is dict and configuration.get('path') == str(logical / relative)
            and len(configuration.get('hashes', [])) == 2
            and len(configuration.get('byteSizes', [])) == 2,
            'Application catalog lacks exact before/after configurations.')
    scratch = _VERIFICATION_SCRATCH.get()
    require(scratch is not None, 'Application catalog requires private recovery scratch.')
    runtime, executable = Path(catalog_runtime_root), Path(node)
    require(executable.resolve(strict=True) == executable and executable.is_file(),
            'Application catalog requires the verified native Node executable.')
    sources = _native_sources(runtime)
    original_families = []
    with tempfile.TemporaryDirectory(prefix='nova-catalog-', dir=scratch) as temporary:
        directory = Path(temporary)
        sides = []
        for position, (index, root, release) in enumerate(zip(indexes, (snapshot, live), app_releases)):
            config_path = root / relative
            raw = catalog_file(config_path, configuration['hashes'][position])
            require(len(raw) == configuration['byteSizes'][position] and len(raw) <= 4 * MAXIMUM,
                    'Application catalog configuration size changed.')
            config = json.loads(raw)
            app_root, manifest = Path(release[0]), release[1]
            expected = set(APP_PLUGINS) - ({DIRECT} if position == 0 else set())
            app_rows = [row for row in index['plugins'] if row.get('pluginId') in APP_PLUGINS]
            require(len(app_rows) == len(expected) and {row['pluginId'] for row in app_rows} == expected,
                    'Application catalog plugin set is outside the exact transition.')
            paths = [_plugin_files(row, app_root, manifest, row['pluginId'], position == 1) for row in app_rows]
            require(type(config.get('plugins')) is dict and type(config['plugins'].get('load')) is dict
                    and type(config['plugins']['load'].get('paths')) is list
                    and all(config['plugins']['load']['paths'].count(path) == 1 for path in paths),
                    'Application catalog plugins are not selected by the actual configuration.')
            # Discovery order comes from the authenticated configuration, not
            # the index whose new Direct insertion position we are checking.
            paths = [path for path in config['plugins']['load']['paths'] if path in paths]
            database = root / selected / 'openclaw-runtime/state/state/openclaw.sqlite'
            identities = sqlite_source_identity(database); original_families.append((database, identities))
            require(shutil.disk_usage(directory).free >= sum(row[0][6] for row in identities.values()) + RESERVE + ALLOWANCE,
                    'Catalog complete-family copy and recovery reserve do not fit.')
            state = directory / str(position); (state / 'state').mkdir(parents=True, mode=0o700)
            for suffix, (_, expected_hash) in identities.items():
                source = Path(str(database) + suffix)
                destination = state / 'state' / ('openclaw.sqlite' + suffix)
                with os.fdopen(os.open(source, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0)), 'rb') as reader:
                    with destination.open('xb') as writer:
                        shutil.copyfileobj(reader, writer, 1024 * 1024)
                destination.chmod(0o600)
                require(digest(destination) == expected_hash, 'Catalog private database-family copy differs.')
            require(sqlite_source_identity(database) == identities, 'Catalog retained database family changed.')
            verify_sqlite_wal(state / 'state/openclaw.sqlite')
            memories = [row for row in index['plugins'] if row.get('pluginId') == 'memory-core']
            require(len(memories) == 1, 'Catalog lacks the existing memory plugin.')
            sides.append(dict(stateRoot=str(state), config=config, paths=paths,
                              uid=(root / selected / 'openclaw-runtime').stat().st_uid,
                              installRecords=index['installRecords'], generatedAtMs=index['generatedAtMs'],
                              memory=memories[0], bundled=[row for row in index['plugins']
                                  if row.get('origin') == 'bundled']))
        payload = json.dumps({'runtime': str(runtime), 'sides': sides}, ensure_ascii=True).encode()
        require(len(payload) <= 36 * 1024 * 1024, 'Catalog derivation input exceeded its bound.')
        env = {'PATH': str(executable.parent), 'HOME': str(directory), 'TMPDIR': str(directory),
               'TEMP': str(directory), 'TMP': str(directory), 'NODE_DISABLE_COMPILE_CACHE': '1'}
        try:
            result = subprocess.run([str(executable), str(Path(__file__).with_name('hosted-retained-catalog.mjs'))],
                                    input=payload, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                    cwd=directory, env=env, timeout=60, check=False)
            require(result.returncode == 0 and len(result.stdout) <= 36 * 1024 * 1024,
                    'Official application catalog derivation failed.')
            derived = json.loads(result.stdout)
        finally:
            require(all(sqlite_source_identity(path) == identity for path, identity in original_families),
                    'Original catalog database family changed during derivation.')
            require(all(_identity(path) == identity for path, identity in sources.items()),
                    'Official catalog source changed during derivation.')
        for position, (index, root, release) in enumerate(zip(indexes, (snapshot, live), app_releases)):
            catalog_file(root / relative, configuration['hashes'][position])
            for row in index['plugins']:
                if row.get('pluginId') in APP_PLUGINS:
                    _plugin_files(row, Path(release[0]), release[1], row['pluginId'], position == 1)
        return _normalize(indexes, derived)
